import 'dart:io';
import 'package:equatable/equatable.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../core/app_logger.dart';import 'utility_bloc.dart';
sealed class ToolDetectionEvent extends Equatable{const ToolDetectionEvent();@override List<Object?>get props=>[];}final class ToolDetectionRequested extends ToolDetectionEvent{const ToolDetectionRequested();}
enum ToolDetectionStatus{initial,loading,success,failure}
class ToolDetectionState extends Equatable{const ToolDetectionState({this.status=ToolDetectionStatus.initial,this.paths=const{},this.error});final ToolDetectionStatus status;final Map<DevUtility,String?>paths;final String?error;bool installed(DevUtility u)=>paths[u]?.isNotEmpty??false;@override List<Object?>get props=>[status,paths,error];}
class ToolDetectionBloc extends Bloc<ToolDetectionEvent,ToolDetectionState>{ToolDetectionBloc():super(const ToolDetectionState()){on<ToolDetectionRequested>(_detect);}Future<void>_detect(ToolDetectionRequested e,Emitter<ToolDetectionState>emit)async{emit(const ToolDetectionState(status:ToolDetectionStatus.loading));try{final paths=<DevUtility,String?>{};for(final u in DevUtility.values){final p=await Process.run('where.exe',[u.executable]);final lines=p.stdout.toString().split(RegExp(r'[\r\n]+')).where((x)=>x.trim().isNotEmpty);paths[u]=p.exitCode==0&&lines.isNotEmpty?lines.first.trim():null;}emit(ToolDetectionState(status:ToolDetectionStatus.success,paths:paths));}catch(x,s){AppLogger.error('Detection failed',x,s);emit(ToolDetectionState(status:ToolDetectionStatus.failure,error:'Detection failed: $x'));}}}
